{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "Unrestricted SageMaker presigned notebook URL creation",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "HIGH",
      "explanation": "The policy permits CreatePresignedNotebookInstanceUrl against Resource "*", allowing principals to obtain authenticated access URLs for any accessible SageMaker notebook instance. This can enable privilege escalation through the notebook instance's execution role."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows listing SageMaker notebook instances"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sagemaker:ListNotebookInstances"
        ]
        Resource = "*"
      },
    ]
  })
}
",
  "fix_summary": "Removed the privilege-escalation-capable CreatePresignedNotebookInstanceUrl permission while retaining the SageMaker notebook listing permission, which requires a wildcard resource. Updated the policy description to reflect its remaining capability."
}
